def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line - add the last field
            break

        # Check if this field is quoted
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote or the end of the quoted field
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote - represents a single quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None

            # After the closing quote, we must have a comma or end of line
            if i < n:
                if line[i] == ',':
                    fields.append(''.join(field))
                    i += 1
                else:
                    # Invalid: closing quote not followed by comma or end
                    return None
            else:
                # End of line after closing quote
                fields.append(''.join(field))
        else:
            # Unquoted field - runs until comma or end of line
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain a double quote
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))
            if i < n:
                # We hit a comma
                i += 1

    return fields

